import{_t as e,it as t,n,rt as r}from"./chunks/framework.uM88Qy9F.js";var i=JSON.parse(`{"title":"约束规则与审批","description":"","frontmatter":{},"headers":[],"relativePath":"backend/approval.md","filePath":"backend/approval.md","lastUpdated":1794049926000}`),a={name:`backend/approval.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="约束规则与审批" tabindex="-1">约束规则与审批 <a class="header-anchor" href="#约束规则与审批" aria-label="Permalink to “约束规则与审批”">​</a></h1><p>本页说明约束规则、会话角色激活与授权申请，适用于后端开发者与权限配置人员。</p><div class="info custom-block"><p class="custom-block-title">本页范围</p><p>三者都在 Access 包。授权申请的审批走 Workflow（审批中心见<a href="./workflow#待办与审批中心">工作流</a>）；Workflow 关掉时授权申请照常列出、不能提交。</p></div><h2 id="约束规则" tabindex="-1">约束规则 <a class="header-anchor" href="#约束规则" aria-label="Permalink to “约束规则”">​</a></h2><h3 id="五种类型" tabindex="-1">五种类型 <a class="header-anchor" href="#五种类型" aria-label="Permalink to “五种类型”">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>判定时机</th><th>含义</th></tr></thead><tbody><tr><td><code>Ssd</code> 静态职责分离</td><td>指派角色、改指派有效期、委托角色、设上级</td><td>同一用户持有的角色（没过期的指派与角色委托，按继承展开）里，同一组不能超过上限个</td></tr><tr><td><code>Dsd</code> 动态职责分离</td><td>会话激活角色</td><td>可以同时持有，但同一会话激活的角色（按继承展开）里，同一组不能超过上限个</td></tr><tr><td><code>MutualExclusion</code> 权限互斥</td><td>给角色或用户直接授予权限码</td><td>同一角色或用户直接持有的权限码里，同一组不能超过上限个</td></tr><tr><td><code>Cardinality</code> 基数</td><td>指派角色、改指派有效期、委托角色</td><td>角色的成员数上限，或用户持有的角色数上限</td></tr><tr><td><code>Condition</code> 条件</td><td>指派或委托规则项里的角色</td><td>按条件引擎判定被指派的用户与发起这次变更的请求，不满足即违规</td></tr></tbody></table><ul><li>规则存在 <code>SysConstraintRule</code>，规则项（角色 ID、权限码或用户 ID，带组号）存在 <code>SysConstraintRuleItem</code>，每条规则至多 200 项；按侧（平台 / 租户）分开。</li><li>编码在本侧唯一、不含空白；条件类的条件写法同<a href="./access-policy#条件属性">访问策略</a>。</li><li>规则带优先级（越大越先求值）与有效期；启用的规则按侧缓存 60 秒，写入在提交之后失效。</li></ul><h3 id="违规处理" tabindex="-1">违规处理 <a class="header-anchor" href="#违规处理" aria-label="Permalink to “违规处理”">​</a></h3><table tabindex="0"><thead><tr><th>方式</th><th>行为</th></tr></thead><tbody><tr><td><code>Deny</code></td><td>拦下变更，<code>ACCESS_CONFLICT_012</code></td></tr><tr><td><code>RequireApproval</code></td><td>拦下变更，等同拒绝，不发起审批</td></tr><tr><td><code>Warning</code></td><td>照常执行，记一条权限变更日志（<code>ConstraintViolation</code>）</td></tr><tr><td><code>Log</code></td><td>照常执行，同样记日志，只是级别不同</td></tr></tbody></table><p><code>ConstraintEnforcer</code> 只拦这次变更新带进来的违规，不因为已有数据已经违规而拒绝无关的变更。批量授予权限时逐个过权限互斥，被拦的那一项失败、其余照常。</p><h3 id="操作" tabindex="-1">操作 <a class="header-anchor" href="#操作" aria-label="Permalink to “操作”">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th></tr></thead><tbody><tr><td><code>constraint-rules.list</code> / <code>get</code></td><td><code>access.constraint-rules.read</code></td></tr><tr><td><code>constraint-rules.create</code> / <code>update</code></td><td><code>access.constraint-rules.create</code> / <code>update</code></td></tr><tr><td><code>constraint-rules.set-status</code></td><td><code>access.constraint-rules.update</code>（启用时重新校验规则项）</td></tr><tr><td><code>constraint-rules.delete</code></td><td><code>access.constraint-rules.delete</code>（批量，连同规则项）</td></tr></tbody></table><p>权限码两侧都有，写操作进操作日志。页面 <code>access.constraint-rules</code>（<code>/access/constraint-rules</code>）。</p><h2 id="会话角色激活" tabindex="-1">会话角色激活 <a class="header-anchor" href="#会话角色激活" aria-label="Permalink to “会话角色激活”">​</a></h2><ul><li><code>SysSessionRole</code> 记每个会话激活了哪些角色（会话 × 角色一行）。登录、刷新、切换租户与模仿时由 Contracts 的 <code>ISessionRoleActivator</code>（Access 实现）选定激活集：持有的角色按排序号、再按编码逐个尝试，加上它会违反拦截类 DSD 规则的不激活。</li><li>令牌的 <code>role</code> 声明只带激活的角色，权限判定与数据范围都按它。</li><li>开会话与续签时有角色被 DSD 停掉或已不再持有，另记一条登录日志（<code>RoleActivation</code>）。</li><li>停用与到期的行保留作查询，原因如 <code>dsd:&lt;规则编码&gt;</code>、<code>not-held</code>。</li></ul><table tabindex="0"><thead><tr><th>操作</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>auth.session-roles</code></td><td>登录即可</td><td>此刻持有的角色与本会话激活的角色</td></tr><tr><td><code>auth.activate-roles</code></td><td>登录即可</td><td>换激活集：会话续用、刷新令牌轮换；要激活的须此刻持有（<code>ACCESS_VALIDATION_050</code>），违反 DSD 即 <code>ACCESS_CONFLICT_012</code>；记登录日志（<code>RoleActivation</code>）；模仿态的会话不能切换</td></tr><tr><td><code>session-roles.list</code> / <code>get</code></td><td><code>access.session-roles.read</code></td><td>管理员查看各会话的激活记录</td></tr></tbody></table><p>前端的「切换角色」在用户菜单里。</p><h2 id="授权申请" tabindex="-1">授权申请 <a class="header-anchor" href="#授权申请" aria-label="Permalink to “授权申请”">​</a></h2><p>用户为自己申请一个角色或一个权限码（二选一：都给是 <code>ACCESS_VALIDATION_056</code>，都不给是 <code>ACCESS_VALIDATION_051</code>），提交即在同一个事务里发起审批业务 <code>permission-request</code> 的流程；审批通过即按期望的有效期指派角色或直授权限，驳回或中止即完结。</p><p>它是 Contracts 审批业务接入（<code>IWorkflowBusinessHandler</code>）的参照实现，见<a href="./workflow#审批业务接入">工作流</a>。表 <code>sys_permission_request</code> 在租户库，平台一侧的申请租户为 <code>platform</code>。</p><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>permission-requests.list</code> / <code>get</code></td><td><code>access.permission-requests.read</code></td><td>这一侧全部的申请，带审批进度。关键字匹配申请人（经用户目录在这一侧按登录名与显示名搜，含停用的账号，取前 200 个）、申请原因与备注；可按申请人、角色、权限码与状态筛选，缺省按提交时间降序</td></tr><tr><td><code>permission-requests.create</code></td><td><code>access.permission-requests.create</code></td><td>申请人要是这一侧的在用账号；角色存在且启用、权限码在这一侧的目录里，期望失效时间晚于现在；同一对象只能有一条待审批的申请（<code>ACCESS_CONFLICT_013</code>）</td></tr><tr><td><code>permission-requests.update</code></td><td><code>access.permission-requests.update</code></td><td>修改自己待审批的申请并重新提交：撤回旧流程、按新内容重新发起，已有的审批意见作废</td></tr><tr><td><code>permission-requests.withdraw</code></td><td><code>access.permission-requests.withdraw</code></td><td>批量；撤回自己待审批的申请，同时撤回流程</td></tr><tr><td><code>permission-requests.set-status</code></td><td><code>access.permission-requests.status</code></td><td>批量；管理员把别人待审批的申请置为已驳回或已撤回（不能置为已批准，<code>ACCESS_VALIDATION_054</code>），同时撤回流程</td></tr></tbody></table><p>权限码两侧都有，写操作进操作日志。</p><ul><li><strong>缺省流程</strong>：当前分区第一次提交时建并发布「管理员审批」：角色 <code>admin</code> 审批，不含申请人自己。可在流程定义里新建版本调整。找不到审批人（如这一侧只有申请人一个管理员）即发起故障 <code>WORKFLOW_CONFLICT_101</code>，申请随之回滚。</li><li><strong>审批与手工处理</strong>：处理人不能处理自己的申请（<code>ACCESS_DENIED_009</code>），且要能授出申请的对象：角色要 <code>access.roles.assign</code>，权限要 <code>access.user-grants.grant</code>（<code>ACCESS_DENIED_010</code>）。</li><li><strong>通过</strong>：重核对象仍可用，角色经指派写入（过约束规则，拦截类违规即失败）、权限经直授写入；任一步失败即结束节点故障、申请保持待审批（<code>ACCESS_CONFLICT_015</code>），处理后在流程实例里重试。直授的权限立即生效，角色在申请人下次换发令牌时生效。</li><li><strong>中止</strong>：管理员取消、终止流程或发起人在审批中心撤回时，待审批的申请置为已撤回。</li><li><strong>状态</strong>：<code>Pending</code> 待审批、<code>Approved</code> 已批准、<code>Rejected</code> 已驳回、<code>Withdrawn</code> 已撤回。期望失效时间已过的另带 <code>isExpectedExpired</code> 标记，不是状态。</li><li><strong>模仿会话</strong>：对授权申请的写操作一律 409 <code>ACCESS_CONFLICT_016</code>：提交、修改重提、撤回、手工处理，以及这张审批单上的同意 / 驳回、转办、加签、发起人撤回，管理员的取消、终止、重试、挂起与恢复（批量里那一项记失败、流程不动）。其他业务的流程不拦。</li><li><strong>Workflow 关掉</strong>：列表照常、进度为空并标「审批未启用」（<code>approvalEnabled</code> 为假），提交与重新提交 503 <code>ACCESS_UNAVAILABLE_002</code>。</li><li><strong>页面</strong>：「授权申请」页（页面码 <code>access.delegations</code>、路由 <code>/access/delegations</code>，菜单权限 <code>access.permission-requests.read</code>）：「申请」页签在前，「委托」页签按 <code>access.delegations.read</code> 显示。审批中心里的单据组件是 <code>access/permission-request-approval/index</code>。</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./permission">权限管理</a> · <a href="./access-policy">访问策略与权限条件</a> · <a href="./workflow">工作流</a></li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};